/// A deferred text draw command. Characters are rasterized through the
/// glyph atlas at render time so UI chrome gets the same ClearType quality
/// as terminal content.
#[derive(Debug, Clone)]
pub struct TextCommand {
    pub text: String,
    pub x: f32,
    pub y: f32,
    pub fg: [f32; 4],
    pub bg: [f32; 4],
    /// When true, renders glyphs with the bold font variant.
    pub bold: bool,
    /// Which rasterizer/layout path should be used for this text run.
    pub font_kind: TextFontKind,
    /// When true, renders with the italic font face instead of a synthetic skew.
    pub italic: bool,
    /// Scale factor for glyph quads (1.0 = normal size, 0.786 = 11/14px).
    pub scale: f32,
    /// Glyph x offsets from a real text layout pass. Empty for monospace runs.
    pub glyph_offsets: Vec<f32>,
    /// Whether the renderer can use subpixel blending against `bg`, or must
    /// fall back to grayscale AA because the backdrop is mixed/unknown.
    pub composite: TextCompositeMode,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TextFontKind {
    TerminalMono,
    UiSans,
    UiSerif,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TextCompositeMode {
    FlatBackground,
    MixedBackground,
}

/// Thin handle passed to widget `build()` methods. Carries actual cell
/// dimensions from the font metrics so widgets can position text correctly.
pub struct UiTextRenderer {
    pub cell_width: f32,
    pub cell_height: f32,
    pub font_size_px: f32,
    pub scale: f32,
    /// Average advance width of the proportional UI font (0 if unavailable).
    pub ui_avg_advance: f32,
    /// Optional real UI text layout path. When present, widths and glyph
    /// positions come from DirectWrite instead of hand-tuned advance math.
    pub layout_engine: Option<Rc<UiTextLayoutEngine>>,
}

impl UiTextRenderer {
    pub fn new(cell_width: f32, cell_height: f32, font_size_px: f32, scale: f32) -> Self {
        Self {
            cell_width,
            cell_height,
            font_size_px,
            scale,
            ui_avg_advance: 0.0,
            layout_engine: None,
        }
    }

    /// Scale a logical pixel value to physical pixels.
    pub fn s(&self, v: f32) -> f32 {
        (v * self.scale).round()
    }

    /// Width in pixels of a string rendered in the terminal monospace font.
    pub fn text_width(&self, s: &str) -> f32 {
        s.chars().count() as f32 * self.cell_width
    }

    /// Exact width of a string rendered in the proportional UI font.
    pub fn text_width_ui(&self, s: &str) -> f32 {
        self.layout_text(UiFontKind::Sans, s, 1.0, false, false)
            .width
    }

    /// Exact width of a string rendered in the proportional UI font at a given scale.
    pub fn text_width_ui_scaled(&self, s: &str, scale: f32) -> f32 {
        self.layout_text(UiFontKind::Sans, s, scale, false, false)
            .width
    }

    /// Exact width of a string rendered in the serif UI font at a given scale.
    pub fn text_width_serif_scaled(
        &self,
        s: &str,
        scale: f32,
        bold: bool,
        italic: bool,
    ) -> f32 {
        self.layout_text(UiFontKind::Serif, s, scale, bold, italic)
            .width
    }

    pub fn glyph_offsets_ui(
        &self,
        s: &str,
        scale: f32,
        bold: bool,
        italic: bool,
        font_kind: TextFontKind,
    ) -> Vec<f32> {
        match font_kind {
            TextFontKind::TerminalMono => Vec::new(),
            TextFontKind::UiSans => self
                .layout_text(UiFontKind::Sans, s, scale, bold, italic)
                .glyph_offsets,
            TextFontKind::UiSerif => self
                .layout_text(UiFontKind::Serif, s, scale, bold, italic)
                .glyph_offsets,
        }
    }

    fn layout_text(
        &self,
        font_kind: UiFontKind,
        s: &str,
        scale: f32,
        bold: bool,
        italic: bool,
    ) -> UiTextLayout {
        if let Some(engine) = &self.layout_engine {
            if let Some(layout) =
                engine.layout(font_kind, s, self.font_size_px * scale, bold, italic)
            {
                return layout;
            }
        }

        let advance = if self.ui_avg_advance > 0.0 {
            self.ui_avg_advance * scale
        } else {
            self.cell_width * 0.75 * scale
        };
        let mut glyph_offsets = Vec::with_capacity(s.chars().count());
        let mut x = 0.0;
        for _ in s.chars() {
            glyph_offsets.push(x);
            x += advance;
        }
        UiTextLayout {
            width: x,
            line_height: self.font_size_px * scale,
            glyph_offsets,
        }
    }
}

/// Collects quad vertices and text commands for UI chrome, then returns them
/// together via `finish()`.
pub struct UiBuilder {
    quads: Vec<QuadVertex>,
    text_commands: Vec<TextCommand>,
    vw: f32,
    vh: f32,
}

impl UiBuilder {
    pub fn new(vw: f32, vh: f32) -> Self {
        Self {
            quads: Vec::new(),
            text_commands: Vec::new(),
            vw,
            vh,
        }
    }

    /// Viewport dimensions in physical pixels.
    pub fn viewport(&self) -> (f32, f32) {
        (self.vw, self.vh)
    }

    /// Solid filled rectangle (flat, no rounding).
    pub fn fill(&mut self, rect: Rect, color: [f32; 4]) {
        self.quads.extend_from_slice(&quad_vertices(
            rect.x, rect.y, rect.width, rect.height,
            self.vw, self.vh, color,
        ));
    }

    /// Flat rectangle with vertical gradient (no rounding).
    pub fn fill_gradient(&mut self, rect: Rect, top_color: [f32; 4], bottom_color: [f32; 4]) {
        self.quads.extend_from_slice(&quad_vertices_gradient(
            rect.x, rect.y, rect.width, rect.height,
            self.vw, self.vh, top_color, bottom_color,
        ));

use godly_terminal_surface::{
    atlas_shader::{AtlasPipeline, AtlasShaderProgram},
    atlas_vertex_builder::{self, CellVertex},
    glyph_atlas::GlyphAtlas,
    glyph_cache::GlyphKey,
    glyph_rasterizer::GlyphRasterizer,
    font_metrics::FontMetrics,
    Color,
};
use godly_protocol::types::RichGridData;

use crate::ui::builder::{TextCommand, TextCompositeMode, TextFontKind};

pub struct TerminalRenderer {
    pipeline: AtlasPipeline,
    glyph_atlas: GlyphAtlas,
    rasterizer: Box<dyn GlyphRasterizer>,
    /// Optional proportional sans-serif rasterizer for UI chrome labels.
    ui_rasterizer: Option<Box<dyn GlyphRasterizer>>,
    /// Optional serif rasterizer for rich UI copy (e.g. poem panel italics).
    ui_serif_rasterizer: Option<Box<dyn GlyphRasterizer>>,
    font_metrics: FontMetrics,
    /// Average advance width of the UI font (for layout estimation).
    ui_avg_advance: f32,
    default_fg: Color,
    default_bg: Color,
}

impl TerminalRenderer {
    pub fn new(
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        format: wgpu::TextureFormat,
        font_metrics: FontMetrics,
        rasterizer: Box<dyn GlyphRasterizer>,
    ) -> Self {
        let pipeline = AtlasPipeline::new(device, queue, format);
        let phys = font_metrics.scaled_for_render();
        let glyph_atlas = GlyphAtlas::new(phys.cell_width, phys.cell_height, phys.baseline_offset);

        Self {
            pipeline,
            glyph_atlas,
            rasterizer,
            ui_rasterizer: None,
            ui_serif_rasterizer: None,
            font_metrics,
            ui_avg_advance: 0.0,
            default_fg: Color::new(0.788, 0.820, 0.851, 1.0),  // GitHub Dark Text #c9d1d9
            default_bg: Color::new(0.055, 0.063, 0.090, 1.0), // GitHub Dark Base #0e1017
        }
    }

    /// Set the proportional UI font rasterizer (e.g., Segoe UI).
    pub fn set_ui_rasterizer(&mut self, mut rasterizer: Box<dyn GlyphRasterizer>) {
        let phys = self.font_metrics.scaled_for_render();
        let metrics = rasterizer.measure(phys.font_size);
        self.ui_avg_advance = metrics.average_advance;
        self.ui_rasterizer = Some(rasterizer);
    }

    pub fn set_ui_serif_rasterizer(&mut self, rasterizer: Box<dyn GlyphRasterizer>) {
        self.ui_serif_rasterizer = Some(rasterizer);
    }

    /// Average advance width of the UI proportional font.
    pub fn ui_avg_advance(&self) -> f32 {
        self.ui_avg_advance
    }

    /// Prepare GPU resources (atlas texture upload, vertex buffer) BEFORE the render pass.
    ///
    /// Renders both terminal grid content and UI chrome text through the
    /// same glyph atlas pipeline for consistent ClearType quality.
    pub fn prepare(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        grid: Option<&RichGridData>,
        full_width: u32,
        full_height: u32,
        offset_x: f32,
        offset_y: f32,
        terminal_w: f32,
        terminal_h: f32,
        ui_text: &[TextCommand],
    ) {
        let mut vertices = if let Some(grid) = grid {
            atlas_vertex_builder::build_vertices(
                grid,
                &mut self.glyph_atlas,
                &self.font_metrics,
                &mut *self.rasterizer,
                self.default_fg,
                self.default_bg,
                full_width,
                full_height,
                offset_x,
                offset_y,
                terminal_w,
                terminal_h,
            )
        } else {
            Vec::new()
        };

        // Rasterize UI chrome text through the same atlas.
        // UI text uses transparent bg (alpha=0) to trigger grayscale AA mode
        // in the atlas shader, so text alpha-composites cleanly over gradient
        // and SDF-rounded backgrounds drawn by the quad pipeline.
        let phys = self.font_metrics.scaled_for_render();
        let vw = full_width as f32;
        let vh = full_height as f32;
        let transparent_bg = [0.0f32, 0.0, 0.0, 0.0];

        for cmd in ui_text {
            let font_size = phys.font_size * cmd.scale;
            let use_ui_font = !matches!(cmd.font_kind, TextFontKind::TerminalMono);
            let use_serif = matches!(cmd.font_kind, TextFontKind::UiSerif);
            let mut fallback_x = cmd.x;

            for (index, ch) in cmd.text.chars().enumerate() {
                let entry = match cmd.font_kind {
                    TextFontKind::TerminalMono => {
                        let key = GlyphKey::new(ch, font_size, cmd.bold, cmd.italic);
                        self.glyph_atlas
                            .get_or_insert(key, &mut *self.rasterizer, font_size)
                    }
                    TextFontKind::UiSans => {
                        let Some(rast) = self.ui_rasterizer.as_mut() else { continue };
                        let key = GlyphKey::new_font(ch, font_size, cmd.bold, cmd.italic, 1);
                        self.glyph_atlas.get_or_insert(key, &mut **rast, font_size)
                    }
                    TextFontKind::UiSerif => {
                        let Some(rast) = self
                            .ui_serif_rasterizer
                            .as_mut()
                            .or(self.ui_rasterizer.as_mut())
                        else {
                            continue;
                        };
                        let key = GlyphKey::new_font(ch, font_size, cmd.bold, cmd.italic, 2);
                        self.glyph_atlas.get_or_insert(key, &mut **rast, font_size)
                    }
                };

                let px = cmd
                    .glyph_offsets
                    .get(index)
                    .map_or(fallback_x, |offset| cmd.x + *offset);
                let py = cmd.y;
                let sc = cmd.scale;
                // For proportional font, use actual glyph slot width from UV;
                // for monospace, use cell_width.
                let pw = if use_ui_font {
                    // Slot width = atlas slot pixel width from UV coords
                    (entry.u1 - entry.u0) * self.glyph_atlas.atlas_width() as f32 * sc
                } else {
                    phys.cell_width * sc
                };
                let ph = phys.cell_height * sc;

                let x0 = px / vw * 2.0 - 1.0;
                let y0 = 1.0 - py / vh * 2.0;
                let x1 = (px + pw) / vw * 2.0 - 1.0;
                let y1 = 1.0 - (py + ph) / vh * 2.0;

                // 6 vertices (2 triangles)
                let v = |pos: [f32; 2], uv: [f32; 2]| CellVertex {
                    position: pos,
                    uv,
                    fg_color: cmd.fg,
                    bg_color: match cmd.composite {
                        TextCompositeMode::FlatBackground => [cmd.bg[0], cmd.bg[1], cmd.bg[2], 1.0],
                        TextCompositeMode::MixedBackground => transparent_bg,
                    },
                };
                let tl = [x0, y0];
                let tr = [x1, y0];
                let bl = [x0, y1];
                let br = [x1, y1];
                let uv_tl = [entry.u0, entry.v0];
                let uv_br = [entry.u1, entry.v1];
                let uv_tr = [uv_br[0], uv_tl[1]];
                let uv_bl = [uv_tl[0], uv_br[1]];

                vertices.push(v(tl, uv_tl));
                vertices.push(v(tr, uv_tr));
                vertices.push(v(bl, uv_bl));
                vertices.push(v(tr, uv_tr));
                vertices.push(v(bl, uv_bl));
                vertices.push(v(br, uv_br));

                if cmd.glyph_offsets.is_empty() {
                    fallback_x += (if use_ui_font || use_serif {
                        entry.advance
                    } else {
                        phys.cell_width
                    }) * sc;
                }
            }
        }

        if vertices.is_empty() { return; }

        let atlas_update = self.glyph_atlas.take_dirty_data();
        let program = AtlasShaderProgram {
            vertices,
            atlas_update,
            viewport_size: (full_width, full_height),
        };
        let primitive = program.build_primitive();
        primitive.prepare(&mut self.pipeline, device, queue);
    }

    /// Draw the prepared terminal content into the render pass.
    pub fn draw(&self, render_pass: &mut wgpu::RenderPass<'_>) {
        // AtlasPipeline stores vertex_count from prepare; draw uses the stored pipeline state
        // We need a dummy primitive to call draw - reuse the pipeline's stored vertex count
        let primitive = godly_terminal_surface::atlas_shader::AtlasShaderProgram {
            vertices: vec![],
            atlas_update: None,
            viewport_size: (0, 0),
        }.build_primitive();
        primitive.draw(&self.pipeline, render_pass);
    }

    pub fn font_metrics(&self) -> &FontMetrics {
        &self.font_metrics
    }
}

