function StatusDot({ color, size = 7 }) {
  return (
    <span
      style={{
        width: size,
        height: size,
        borderRadius: "50%",
        backgroundColor: color,
        display: "inline-block",
        flexShrink: 0,
      }}
    />
  );
}

function Badge({ count, color }) {
  if (!count) return null;
  return (
    <span
      style={{
        backgroundColor: color,
        color: "#fff",
        fontSize: 9,
        fontWeight: 700,
        borderRadius: 7,
        padding: "1px 5px",
        minWidth: 16,
        height: 16,
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        lineHeight: 1,
      }}
    >
      {count}
    </span>
  );
}

function ThoughtsBlock({ count, items, defaultOpen = false }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div style={{ margin: "8px 0 6px" }}>
      <div
        onClick={() => setOpen(!open)}
        style={{
          display: "flex",
          alignItems: "center",
          gap: 6,
          cursor: "pointer",
          color: "#6e7681",
          fontSize: 12,
          userSelect: "none",
        }}
      >
        <span style={{ color: "#22c55e", fontSize: 13 }}>Ô£ô</span>
        <span>{count} thoughts {open ? "Ôû¥" : "Ôû©"}</span>
      </div>
      {open && (
        <div style={{ paddingLeft: 20, marginTop: 4 }}>
          {items.map((item, i) => (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 6,
                color: "#484f58",
                fontSize: 12,
                padding: "1px 0",
              }}
            >
              <span style={{ color: "#3b4048" }}>┬À</span>
              <span>{item}</span>
              <span style={{ color: "#3b4048", marginLeft: 2 }}>Ôû©</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function InlineContent({ children }) {
  if (!children) return null;
  return (
    <span>
      {children.map((c, i) => {
        if (c.link) {
          return (
            <span key={i} style={{ color: "#58a6ff", textDecoration: "underline", cursor: "pointer" }}>
