        Ok("native") => FrontendMode::Native,
        Ok("shadow") => FrontendMode::Shadow,
        _ => FrontendMode::Native,
    }
}

/// Shell type matching the existing Tauri app's ShellType
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, ts_rs::TS)]
#[ts(export)]
#[serde(rename_all = "snake_case")]
pub enum ShellType {
    Windows,
    Pwsh,
    Cmd,
    Wsl {
        distribution: Option<String>,
    },
    Custom {
        program: String,
        args: Option<Vec<String>>,
    },
}

impl ShellType {
    /// Human-readable display name (extracts basename for Custom).
    pub fn display_name(&self) -> String {
        match self {
            ShellType::Windows => "powershell".to_string(),
            ShellType::Pwsh => "pwsh".to_string(),
            ShellType::Cmd => "cmd".to_string(),
            ShellType::Wsl { distribution } => {
                distribution.clone().unwrap_or_else(|| "wsl".to_string())
            }
            ShellType::Custom { program, .. } => {
                // Handle both `/` and `\` separators so Windows paths work on all platforms
                let filename = program.rsplit(['\\', '/']).next().unwrap_or(program);
                filename.strip_suffix(".exe").unwrap_or(filename).to_string()
            }
        }
    }
}

impl Default for ShellType {
    fn default() -> Self {
        ShellType::Windows
    }
}

