                    let fog_h = s(8.0);
                    let fog_rect = ui::widget::Rect {
                        x: layout.terminal.x,
                        y: layout.terminal.y + layout.terminal.height - fog_h,
                        width: layout.terminal.width,
                        height: fog_h,
